{
  "findings": [
    {
      "check_id": "CKV_AWS_25",
      "title": "RDP exposed to the public internet",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "The ingress rule permits RDP on TCP port 3389 from 0.0.0.0/0, allowing connection attempts from any internet address."
    },
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group rule lacks a description",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "The security group rule has no description documenting its purpose, making review and maintenance more difficult."
    }
  ],
  "patched_code": "resource \"aws_security_group_rule\" \"changeme_remote_exec_inline_security_group_rule_incoming_rdp\" {\n  description       = \"Allow RDP from private network addresses\"\n  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id\n  type              = \"ingress\"\n  from_port         = 3389\n  to_port           = 3389\n  protocol          = \"tcp\"\n  cidr_blocks       = [\"10.0.0.0/8\"]\n}\n",
  "fix_summary": "Restricted RDP ingress from the entire internet to private RFC1918 addresses in 10.0.0.0/8. Added a description documenting the rule's purpose."
}
